import { Injectable, inject, signal } from '@angular/core';
import type { FieldConfig, RawValue, RawValues, Step1Output } from '../shared/field-config.model';
import { validateForm } from '../shared/field-validators';
import { hydrate, toOutput } from '../shared/field-values';
import { CLOCK } from './clock';

const STORAGE_KEY = 'quote-wizard';
const VERSION = 1;

const isRecord = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

/**
 * Wizard state (ADR-0003). Holds the raw editing values of step 1 for one country, written to
 * `sessionStorage` on every change, and the typed output that exists only after a valid
 * "Continuar". Values are never logged. When storage is unavailable the state lives in memory.
 */
@Injectable({ providedIn: 'root' })
export class QuoteStore {
  private readonly clock = inject(CLOCK);
  private readonly countrySignal = signal<string | null>(null);
  private readonly valuesSignal = signal<RawValues>({});
  private readonly outputSignal = signal<Step1Output | null>(null);
  private warnedAboutStorage = false;

  readonly country = this.countrySignal.asReadonly();
  readonly values = this.valuesSignal.asReadonly();
  readonly step1Output = this.outputSignal.asReadonly();

  constructor() {
    this.restore();
  }

  /** Enters a supported country's context; another country's stored state is discarded. */
  enterCountry(code: string): void {
    if (this.countrySignal() !== code) {
      this.valuesSignal.set({});
      this.outputSignal.set(null);
      this.countrySignal.set(code);
      this.clearStorage();
    }
    this.persist();
  }

  setValue(key: string, value: RawValue): void {
    this.valuesSignal.update((values) => ({ ...values, [key]: value }));
    this.outputSignal.set(null);
    this.persist();
  }

  /** Drops values of keys no longer configured and clears select values whose option is gone. */
  prune(configs: FieldConfig[]): void {
    const pruned: RawValues = {};
    for (const [key, value] of Object.entries(this.valuesSignal())) {
      const config = configs.find((c) => c.key === key);
      if (!config) continue;
      const optionGone = config.type === 'select' && typeof value === 'string' && value !== '' && !config.options?.some((o) => o.value === value);
      pruned[key] = optionGone ? '' : value;
    }
    this.valuesSignal.set(pruned);
    this.persist();
  }

  /** True when the stored values are valid for the given configuration, on the clock's today. */
  isStep1Valid(configs: FieldConfig[]): boolean {
    const model = hydrate(configs, this.valuesSignal());
    return Object.keys(validateForm(configs, model, this.clock())).length === 0;
  }

  /** The typed output, only when every field is valid; otherwise `null` and no output is kept. */
  completeStep1(configs: FieldConfig[]): Step1Output | null {
    const country = this.countrySignal();
    if (country === null || !this.isStep1Valid(configs)) {
      this.outputSignal.set(null);
      return null;
    }
    const output: Step1Output = { country, values: toOutput(configs, hydrate(configs, this.valuesSignal())) };
    this.outputSignal.set(output);
    return output;
  }

  private restore(): void {
    let raw: string | null;
    try {
      raw = sessionStorage.getItem(STORAGE_KEY);
    } catch {
      this.warnStorageOnce();
      return;
    }
    if (raw === null) return;
    const entry = this.parseEntry(raw);
    if (entry === null) {
      console.warn('quote-wizard: the stored entry is invalid and was discarded');
      this.clearStorage();
      return;
    }
    this.countrySignal.set(entry.country);
    this.valuesSignal.set(entry.values);
  }

  private parseEntry(raw: string): { country: string; values: RawValues } | null {
    let parsed: unknown;
    try {
      parsed = JSON.parse(raw);
    } catch {
      return null;
    }
    if (!isRecord(parsed) || parsed['version'] !== VERSION) return null;
    const country = parsed['country'];
    if (typeof country !== 'string' || !/^[A-Z]{2}$/.test(country)) return null;
    const step1 = parsed['step1'];
    if (!isRecord(step1)) return null;
    const stored = step1['values'];
    if (!isRecord(stored)) return null;
    const values: RawValues = {};
    for (const [key, value] of Object.entries(stored)) {
      if (typeof value !== 'string' && typeof value !== 'boolean') return null;
      values[key] = value;
    }
    return { country, values };
  }

  private persist(): void {
    const country = this.countrySignal();
    if (country === null) return;
    try {
      sessionStorage.setItem(STORAGE_KEY, JSON.stringify({ version: VERSION, country, step1: { values: this.valuesSignal() } }));
    } catch {
      this.warnStorageOnce();
    }
  }

  private clearStorage(): void {
    try {
      sessionStorage.removeItem(STORAGE_KEY);
    } catch {
      this.warnStorageOnce();
    }
  }

  private warnStorageOnce(): void {
    if (this.warnedAboutStorage) return;
    this.warnedAboutStorage = true;
    console.warn('quote-wizard: sessionStorage is unavailable, the state is kept in memory only');
  }
}
import { inject } from '@angular/core';
import { CanActivateFn, RedirectCommand, Router } from '@angular/router';
import { CountryStore } from './country-store';
import { FormFieldStore } from './form-field-store';
import { QuoteStore } from './quote-store';

/**
 * Step 2 is reachable only when the wizard state holds step 1 values for the route's country that
 * pass the same validators against this page load's configuration (ADR-0001, US-01-AC-19).
 * Otherwise it redirects to step 1, replacing the blocked address in the history.
 */
export const wizardStepGuard: CanActivateFn = async (route) => {
  const router = inject(Router);
  const countries = inject(CountryStore);
  const fields = inject(FormFieldStore);
  const quote = inject(QuoteStore);

  const param = (route.paramMap.get('country') ?? route.parent?.paramMap.get('country') ?? '').toLowerCase();
  const toStep1 = new RedirectCommand(router.parseUrl(`/${param}/datos`), { replaceUrl: true });

  await countries.ensureLoaded();
  const country = countries.find(param);
  if (!country || quote.country() !== country.code) return toStep1;
  try {
    const configs = await fields.load(country.code);
    return configs.length > 0 && quote.isStep1Valid(configs) ? true : toStep1;
  } catch {
    return toStep1;
  }
};
import { InjectionToken } from '@angular/core';

/** The source of "today" for every validator (US-01-Q-06). Tests provide a fixed one. */
export const CLOCK = new InjectionToken<() => Date>('CLOCK', {
  providedIn: 'root',
  factory: () => () => new Date(),
});
import { Routes } from '@angular/router';
import { supportedCountryGuard } from './core/supported-country-guard';
import { wizardStepGuard } from './core/wizard-step-guard';
import { CountryChooserPage } from './features/country/country-chooser-page';
import { UnknownCountryPage } from './features/country/unknown-country-page';
import { QuoteFormPage } from './features/quote-form/quote-form-page';

/** Wizard routes per ADR-0001. Step slugs are Spanish because they are user-visible. */
export const routes: Routes = [
  { path: '', pathMatch: 'full', component: CountryChooserPage },
  {
    path: ':country',
    canMatch: [supportedCountryGuard],
    children: [
      { path: '', pathMatch: 'full', redirectTo: 'datos' },
      { path: 'datos', component: QuoteFormPage },
      // US-02 attaches its page here without changing the address or the guard (US-01-Q-27).
      { path: 'planes', canActivate: [wizardStepGuard], children: [] },
      { path: '**', redirectTo: 'datos' },
    ],
  },
  { path: '**', component: UnknownCountryPage },
];
import { HttpClient } from '@angular/common/http';
import { Observable, timeout } from 'rxjs';

/** Limit for every content request: after 10 s the load is treated as failed (US-01-Q-17). */
export const CONTENT_TIMEOUT_MS = 10_000;

/**
 * GET on the same-origin content API (relative `/api`, ADR-0002). Read-only: no body, no
 * Authorization header, and nothing from the wizard state ever goes into the request.
 */
export function contentGet(http: HttpClient, path: string, params: Record<string, string>): Observable<unknown> {
  return http.get<unknown>(`/api/${path}`, { params }).pipe(timeout(CONTENT_TIMEOUT_MS));
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable, map } from 'rxjs';
import { parseFieldConfigs } from '../shared/field-config';
import type { FieldConfig } from '../shared/field-config.model';
import { contentGet } from './content-request';

@Injectable({ providedIn: 'root' })
export class FormFieldApi {
  private readonly http = inject(HttpClient);

  /** One request per country, filtered by the published country code (ADR-0001). */
  list(countryCode: string): Observable<FieldConfig[]> {
    return contentGet(this.http, 'form-fields', {
      'filters[country][code][$eq]': countryCode,
      'populate[options]': 'true',
      'populate[rules]': 'true',
      sort: 'sortOrder:asc',
      'pagination[pageSize]': '100',
    }).pipe(map(parseFieldConfigs));
  }
}

