/**
 * Boots the real application routes (`appConfig` + `routes`) in the zoneless TestBed with the
 * content API replaced by a `ContentServer`. Component tests of the wizard go through the router,
 * as a person does, so they do not depend on component class names, selectors or input bindings.
 *
 * Usage:
 *   beforeEach(() => configureAppTest());
 *   it('...', async () => {
 *     const app = await createAppTest();
 *     await app.open('/co/datos');
 *     ... act on app.root, then `await app.settle()` ...
 *   });
 *
 * A test that scripts a request to never be answered (`'hang'`) must call `vi.useFakeTimers()`
 * BEFORE `createAppTest()` and restore real timers afterwards; it then advances time itself.
 */
import { Location } from '@angular/common';
import { provideLocationMocks } from '@angular/common/testing';
import { provideHttpClientTesting, HttpTestingController } from '@angular/common/http/testing';
import { TestBed } from '@angular/core/testing';
import { Router } from '@angular/router';
import { RouterTestingHarness } from '@angular/router/testing';
import { vi } from 'vitest';
import { appConfig } from '../app/app.config';
import { CLOCK } from '../app/core/clock';
import { ContentServer } from './content-server';
import { SPEC_TODAY, fixedClock } from './clock';

export interface AppTestOptions {
  /** Local calendar date the clock answers. Defaults to the spec's 2026-11-20. */
  today?: Date;
}

export function configureAppTest(options: AppTestOptions = {}): void {
  sessionStorage.clear();
  TestBed.configureTestingModule({
    providers: [
      ...appConfig.providers,
      provideHttpClientTesting(),
      provideLocationMocks(),
      { provide: CLOCK, useValue: fixedClock(options.today ?? SPEC_TODAY) },
    ],
  });
}

export interface AppTest {
  harness: RouterTestingHarness;
  server: ContentServer;
  router: Router;
  location: Location;
  /** The host element of the application (everything the user sees). */
  readonly root: HTMLElement;
  /** Start a navigation without waiting for it (use with `'hang'` behaviours). */
  begin(url: string): Promise<unknown>;
  /** Navigate, answer the content requests, wait until the page has rendered. */
  open(url: string): Promise<void>;
  /** Answer pending content requests and wait for rendering after an action. */
  settle(): Promise<void>;
  /** Path of the current history entry, as the browser would show it. */
  path(): string;
}

export async function createAppTest(): Promise<AppTest> {
  const http = TestBed.inject(HttpTestingController);
  const server = new ContentServer(http);
  const router = TestBed.inject(Router);
  const location = TestBed.inject(Location);
  // The router only listens to browser back/forward after bootstrap; a TestBed has no bootstrap.
  router.setUpLocationChangeListener();
  const harness = await RouterTestingHarness.create();

  const settle = async (): Promise<void> => {
    await server.drain();
    if (vi.isFakeTimers()) {
      await vi.advanceTimersByTimeAsync(50);
      TestBed.tick();
    } else {
      await harness.fixture.whenStable();
    }
  };

  return {
    harness,
    server,
    router,
    location,
    get root(): HTMLElement {
      return harness.fixture.nativeElement as HTMLElement;
    },
    begin: (url) => harness.navigateByUrl(url),
    async open(url) {
      const navigation = harness.navigateByUrl(url);
      await settle();
      await navigation;
      await settle();
    },
    settle,
    path: () => location.path(),
  };
}
/**
 * A scripted stand-in for the Strapi content API behind the same-origin proxy (ADR-0002), built on
 * Angular's `HttpTestingController`. Tests change `countries` and `fields` to script success, an
 * HTTP error, or no answer at all.
 *
 * Why `drain()` exists: in a zoneless TestBed, `fixture.whenStable()` waits for in-flight HTTP
 * requests, so a test that awaits it before answering the request never finishes. `drain()`
 * answers requests as they appear until the application has been idle for a few macrotasks.
 *
 * It matches requests by URL only (`/api/countries`, `/api/form-fields` with
 * `filters[country][code][$eq]=<CODE>`), so the tests do not depend on how the API client is built.
 */
import { HttpTestingController, TestRequest } from '@angular/common/http/testing';
import { vi } from 'vitest';
import { seedCountryItems, seedStrapiItems, strapiListResponse, type StrapiItem } from './seed-fixtures';

export type Behaviour = StrapiItem[] | 'error' | 'hang';

export interface RecordedRequest {
  method: string;
  /** The URL with its query string, percent-decoded (brackets and `$` readable). */
  url: string;
  kind: 'countries' | 'form-fields' | 'other';
  /** For `form-fields`: the value of `filters[country][code][$eq]`. */
  countryCode?: string;
  /** True when the request carried an `Authorization` header. */
  hasAuthorization: boolean;
}

/** Let the event loop run one macrotask (works with real and with fake timers). */
export async function pump(): Promise<void> {
  if (vi.isFakeTimers()) {
    await vi.advanceTimersByTimeAsync(0);
  } else {
    await new Promise<void>((resolve) => setTimeout(resolve, 0));
  }
}

export class ContentServer {
  countries: Behaviour = seedCountryItems();
  fields: Record<string, Behaviour> = { CO: seedStrapiItems('CO'), CL: seedStrapiItems('CL') };
  readonly requests: RecordedRequest[] = [];

  constructor(private readonly http: HttpTestingController) {}

  requestsOf(kind: RecordedRequest['kind']): RecordedRequest[] {
    return this.requests.filter((r) => r.kind === kind);
  }

  /** Answer every request that appears, until nothing new arrives for three macrotasks. */
  async drain(): Promise<void> {
    let idle = 0;
    while (idle < 3) {
      await pump();
      const open = this.http.match(() => true);
      if (open.length === 0) {
        idle++;
        continue;
      }
      idle = 0;
      for (const req of open) this.answer(req);
    }
  }

  private answer(req: TestRequest): void {
    const url = decodeURIComponent(req.request.urlWithParams);
    const hasAuthorization = req.request.headers.has('Authorization');
    if (req.request.method === 'GET' && /^(https?:\/\/[^/]+)?\/api\/countries(\?|$)/.test(url)) {
      this.requests.push({ method: 'GET', url, kind: 'countries', hasAuthorization });
      this.respond(req, this.countries);
      return;
    }
    if (req.request.method === 'GET' && /^(https?:\/\/[^/]+)?\/api\/form-fields(\?|$)/.test(url)) {
      const code = /filters\[country\]\[code\]\[\$eq\]=([^&]+)/.exec(url)?.[1];
      this.requests.push({ method: 'GET', url, kind: 'form-fields', countryCode: code, hasAuthorization });
      this.respond(req, (code !== undefined ? this.fields[code] : undefined) ?? []);
      return;
    }
    this.requests.push({ method: req.request.method, url, kind: 'other', hasAuthorization });
    req.flush({ error: { status: 404, name: 'NotFoundError', message: 'Not Found' } }, { status: 404, statusText: 'Not Found' });
  }

  private respond(req: TestRequest, behaviour: Behaviour): void {
    if (behaviour === 'hang') return; // never answered: the client's own timeout must fire
    if (behaviour === 'error') {
      req.flush(
        { data: null, error: { status: 500, name: 'InternalServerError', message: 'Internal Server Error' } },
        { status: 500, statusText: 'Internal Server Error' },
      );
      return;
    }
    req.flush(strapiListResponse(behaviour));
  }
}
/**
 * Calendar helpers for the injectable clock (US-01-Q-06): "today" is a local calendar date read
 * through the `CLOCK` token. Tests never depend on the real current date.
 */

/** A local date at 09:30 (month is 1-12), so the time of day never decides a result by accident. */
export function day(year: number, month: number, dayOfMonth: number, hours = 9, minutes = 30, seconds = 0): Date {
  return new Date(year, month - 1, dayOfMonth, hours, minutes, seconds);
}

/** A `CLOCK` value that always answers the given instant (a fresh Date each call). */
export function fixedClock(now: Date): () => Date {
  return () => new Date(now.getTime());
}

/** The date the spec pins for most scenarios: 2026-11-20 (valid vehicle years 2006-2027). */
export const SPEC_TODAY = day(2026, 11, 20);
/**
 * DOM helpers for component tests. Queries go through what a person or assistive technology
 * perceives: the label text, the button name, the described-by text and the alert regions.
 * They never use component classes, ids or internal test hooks.
 */

/** Label text as a person reads it: whitespace collapsed, the required marker "*" removed. */
export function normalise(text: string | null | undefined): string {
  return (text ?? '').replace(/\*/g, '').replace(/\s+/g, ' ').trim();
}

export type Control = HTMLInputElement | HTMLSelectElement;

/** All labels of the page, in document order, as text. */
export function allLabels(root: ParentNode): string[] {
  return Array.from(root.querySelectorAll('label'))
    .map((l) => normalise(l.textContent))
    .filter((t) => t.length > 0);
}

/** The control a label names (by `for` or by nesting), or null when no such label exists. */
export function maybeControl(root: ParentNode, label: string): Control | null {
  for (const l of Array.from(root.querySelectorAll('label'))) {
    if (normalise(l.textContent) === label && l.control) return l.control as Control;
  }
  return null;
}

export function control(root: ParentNode, label: string): Control {
  const found = maybeControl(root, label);
  if (!found) throw new Error(`No control is labelled "${label}"`);
  return found;
}

/** Every native control that holds a value (inputs and selects), in document order. */
export function allControls(root: ParentNode): Control[] {
  return Array.from(root.querySelectorAll<Control>('input, select'));
}

export function button(root: ParentNode, name: string): HTMLButtonElement {
  const found = Array.from(root.querySelectorAll('button')).find((b) => normalise(b.textContent) === name);
  if (!found) throw new Error(`No button named "${name}"`);
  return found as HTMLButtonElement;
}

export function maybeButton(root: ParentNode, name: string): HTMLButtonElement | null {
  return (Array.from(root.querySelectorAll('button')).find((b) => normalise(b.textContent) === name) as HTMLButtonElement | undefined) ?? null;
}

export function typeInto(el: Control, text: string): void {
  el.value = text;
  el.dispatchEvent(new Event('input', { bubbles: true }));
}

/** Leave a control (the "touched" moment of Signal Forms). */
export function leave(el: Control): void {
  el.dispatchEvent(new FocusEvent('blur'));
  el.dispatchEvent(new FocusEvent('focusout', { bubbles: true }));
}

/** Pick the option whose visible text matches (a person chooses by what they read). */
export function choose(select: HTMLSelectElement, optionText: string): void {
  const option = Array.from(select.options).find((o) => normalise(o.textContent) === optionText);
  if (!option) throw new Error(`No option "${optionText}"`);
  select.value = option.value;
  select.dispatchEvent(new Event('input', { bubbles: true }));
  select.dispatchEvent(new Event('change', { bubbles: true }));
}

export function setChecked(el: HTMLInputElement, checked: boolean): void {
  if (el.checked !== checked) el.click();
}

/**
 * Fill the form with values keyed by visible label. A `null` value leaves the control untouched.
 * Selects take the option text, checkboxes a boolean, everything else a string.
 */
export function fillForm(root: ParentNode, values: Record<string, string | boolean | null>): void {
  for (const [label, value] of Object.entries(values)) {
    if (value === null) continue;
    const el = control(root, label);
    if (el instanceof HTMLSelectElement) {
      choose(el, value as string);
    } else if (el.type === 'checkbox') {
      setChecked(el, value as boolean);
    } else {
      typeInto(el, value as string);
    }
  }
}

/** The text of every element the control points at with aria-describedby (help text, error). */
export function describedText(el: Control): string {
  const ids = (el.getAttribute('aria-describedby') ?? '').split(/\s+/).filter(Boolean);
  return ids
    .map((id) => normalise(el.ownerDocument.getElementById(id)?.textContent))
    .filter(Boolean)
    .join(' ');
}

/** Non-empty texts of the alert regions of the page. */
export function alertTexts(root: ParentNode): string[] {
  return Array.from(root.querySelectorAll('[role="alert"]'))
    .map((e) => normalise(e.textContent))
    .filter((t) => t.length > 0);
}

/** Controls currently exposed as invalid. */
export function invalidControls(root: ParentNode): Control[] {
  return allControls(root).filter((c) => c.getAttribute('aria-invalid') === 'true');
}

export function isExposedAsRequired(el: Control): boolean {
  return el.required || el.getAttribute('aria-required') === 'true';
}

/** The labels of the controls that currently show an error, in document order. */
export function labelsWithErrors(root: ParentNode): string[] {
  return invalidControls(root).map((c) => normalise(c.labels?.[0]?.textContent));
}

/** Current value of a control as a person sees it (checkbox: boolean, select: the option text). */
export function shownValue(el: Control): string | boolean {
  if (el instanceof HTMLSelectElement) return normalise(el.selectedOptions[0]?.textContent);
  if (el.type === 'checkbox') return el.checked;
  return el.value;
}
/**
 * Helpers to run router guards in an injection context, as the router would, without a browser.
 */
import { TestBed } from '@angular/core/testing';
import { isObservable, firstValueFrom } from 'rxjs';
import {
  convertToParamMap,
  RedirectCommand,
  Router,
  UrlSegment,
  type ActivatedRouteSnapshot,
  type CanMatchFn,
  type GuardResult,
  type MaybeAsync,
  type RouterStateSnapshot,
} from '@angular/router';

/** Wait for a guard result whatever its shape (value, promise, observable). */
export async function settleGuard(result: MaybeAsync<GuardResult>): Promise<GuardResult> {
  if (isObservable(result)) return firstValueFrom(result);
  return await result;
}

export function runInContext<T>(fn: () => T): T {
  return TestBed.runInInjectionContext(fn);
}

/**
 * The snapshot a `canActivate` guard of `/:country/planes` receives. The country is offered the
 * ways the router can expose it (own params, parent params), so the guard may read it any of them.
 */
export function stepSnapshot(country: string): ActivatedRouteSnapshot {
  const params = { country };
  const paramMap = convertToParamMap(params);
  const parent = { params, paramMap, parent: null, url: [new UrlSegment(country, {})] };
  return { params, paramMap, parent, url: [new UrlSegment('planes', {})] } as unknown as ActivatedRouteSnapshot;
}

export function stepState(url: string): RouterStateSnapshot {
  return { url } as unknown as RouterStateSnapshot;
}

export function segmentsOf(...paths: string[]): UrlSegment[] {
  return paths.map((p) => new UrlSegment(p, {}));
}

/** Where a guard redirects to, as the serialized address, plus its navigation behaviour. */
export function redirectOf(result: GuardResult): { url: string; replaceUrl: boolean | undefined } | null {
  if (!(result instanceof RedirectCommand)) return null;
  const router = TestBed.inject(Router);
  return { url: router.serializeUrl(result.redirectTo), replaceUrl: result.navigationBehaviorOptions?.replaceUrl };
}

/** The third `canMatch` argument (the partial snapshot); the guard under test must not need it. */
export function emptyMatchSnapshot(): Parameters<CanMatchFn>[2] {
  return {} as Parameters<CanMatchFn>[2];
}

