      ['key with an upper-case letter', { key: 'Probe-upper' }],
      ['key starting with a digit', { key: '4plan' }],
      ['key with an underscore', { key: 'plan_4' }],
      ['key empty', { key: '' }],
      ['coverages null', { coverages: null }],
