import { expect, test, type APIRequestContext, type Request } from '@playwright/test';
import { STRAPI_URL, adminCredentials } from './support/env';
import { continuar, field, fillColombia } from './support/form';
import {
  CL_HIDDEN_NAMES,
  CL_PLAN_NAMES,
  CL_PRICES,
  CO_PLAN_NAMES,
  TODAY,
  createPlan,
  createPlanToken,
